const ga = $('Pobierz dane GA4').first().json;
const nazwy = (ga.metricHeaders || []).map((m) => m.name);
const zakresy = {};
for (const r of ga.rows || []) {
  const z = r.dimensionValues?.[0]?.value || 'teraz';
  zakresy[z] = Object.fromEntries(nazwy.map((n, i) => [n, Number(r.metricValues?.[i]?.value || 0)]));
}
const t = zakresy.teraz || {};
const w = zakresy.wczesniej || {};
const zm = (k) => (w[k] ? (((t[k] || 0) - w[k]) / w[k]) * 100 : null);
const f = (n) => Number(n || 0).toLocaleString('pl-PL', { maximumFractionDigits: 1 });
const linia = (etykieta, k, proc) => etykieta + ': ' + (proc ? f((t[k] || 0) * 100) + '%' : f(t[k])) + (zm(k) === null ? '' : ' (' + (zm(k) >= 0 ? '+' : '') + f(zm(k)) + '% r/r tydzień)');
const frazy = ($('Pobierz frazy z Search Console').first().json.rows || [])
  .map((r) => '• ' + r.keys?.[0] + ' – ' + r.clicks + ' klik., ' + r.impressions + ' wyśw., poz. ' + f(r.position));
const tabela = [linia('Sesje', 'sessions'), linia('Użytkownicy', 'totalUsers'), linia('Kluczowe zdarzenia', 'keyEvents'), linia('Zaangażowanie', 'engagementRate', true)].join('\n');
return [{ json: { tabela, frazy: frazy.join('\n') || '(brak danych)' } }];

const SYSTEM = "Jesteś analitykiem stron internetowych małych firm. Na podstawie liczb napisz 2-3 zdania prostym językiem (bez żargonu) i maks. 3 konkretne rekomendacje. Używaj tylko podanych liczb.\n\nOdpowiedz WYŁĄCZNIE poprawnym obiektem JSON z polami: {\"komentarz\": tekst, \"rekomendacje\": tablica krótkich zdań}. Nie wymyślaj faktów, cen ani danych, których nie ma w treści.";
const user = `Ruch (ostatnie 7 dni vs poprzednie 7):\n${$json.tabela}\n\nNajważniejsze frazy z Google:\n${$json.frazy}`;
return {
  json: {
    ...$json,
    _aiPrompt: String(user).slice(0, 12000),
  },
};

// Łączymy dane wejściowe (sprzed wywołania AI) z odpowiedzią modelu.
const ctx = { ...$('AI: prompt (komentarz do ruchu)').item.json };
delete ctx._aiPrompt;
let out = {};
let aiError = '';
try {
  const raw = $json.output ?? '';
  out = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (!out || typeof out !== 'object' || Array.isArray(out)) throw new Error('to nie obiekt');
} catch (e) {
  aiError = 'Nie udało się odczytać odpowiedzi AI: ' + e.message;
  out = {};
}
const defaults = {"komentarz":"","rekomendacje":""};
for (const [k, v] of Object.entries(defaults)) if (out[k] === undefined || out[k] === null) out[k] = v;
for (const [k, v] of Object.entries(out)) if (typeof v === 'string') out[k] = v.slice(0, 4000);

return { json: { ...ctx, ...out, _aiOk: !aiError, _aiError: aiError } };

